$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$tempGate=Join-Path $root 'docs\finance\evidence\.decision-gates-test.json';$tempDecision=Join-Path $root 'docs\finance\evidence\.decision-test.json';$tempArtifact=Join-Path $root 'docs\finance\evidence\.decision-artifact-test.json'
try{
 [IO.File]::WriteAllText($tempArtifact,'{"synthetic":true}',[Text.UTF8Encoding]::new($false));$hash=(Get-FileHash $tempArtifact -Algorithm SHA256).Hash.ToLowerInvariant();$relative=[IO.Path]::GetRelativePath($root,$tempArtifact).Replace('\','/');$g=Get-Content -Raw (Join-Path $root 'docs\finance\uat-preproduction-gates.json')|ConvertFrom-Json -Depth 30
 foreach($gate in @($g.gates|Where-Object id -ne 'FIN-G12')){$gate.status='PASSED';$gate.blockingReason=$null;$entries=@();foreach($role in @($gate.owner)+@($gate.approvers)){$entries+=[pscustomobject]@{path=$relative;sha256=$hash;signedBy="synthetic-$role";signedRole=$role;signedAtUtc='2026-11-03T00:00:00Z'}};$gate.evidence=$entries};[IO.File]::WriteAllText($tempGate,($g|ConvertTo-Json -Depth 30),[Text.UTF8Encoding]::new($false))
 $d=Get-Content -Raw (Join-Path $root 'docs\finance\preproduction-decision.json')|ConvertFrom-Json -Depth 30;$d.decision='GO';$d.decisionRecordId='FIN-GO-SYNTHETIC-001';$d.releaseCommit='a'*40;$d.changeWindowStartUtc='2026-11-03T03:00:00Z';$d.changeWindowEndUtc='2026-11-03T04:00:00Z';$d.deploymentOwnerIdentitySha256='1'*64;$d.releaseManifestPath=$relative;$d.releaseManifestSha256=$hash;$d.rollbackEvidencePath=$relative;$d.rollbackEvidenceSha256=$hash;$chars=@('b','c','d','e','f');for($i=0;$i -lt 5;$i++){$d.signoffs[$i].identitySha256=$chars[$i]*64;$d.signoffs[$i].signedAtUtc='2026-11-03T02:00:00Z'};[IO.File]::WriteAllText($tempDecision,($d|ConvertTo-Json -Depth 30),[Text.UTF8Encoding]::new($false))
 & (Join-Path $PSScriptRoot 'Test-FinancePreproductionDecision.ps1') -RequireGo -DecisionFile $tempDecision -GateFile $tempGate
 $g.gates[10].status='PENDING';$g.gates[10].blockingReason='Synthetic missing gate';$g.gates[10].evidence=@();[IO.File]::WriteAllText($tempGate,($g|ConvertTo-Json -Depth 30),[Text.UTF8Encoding]::new($false));$rejected=$false;try{& (Join-Path $PSScriptRoot 'Test-FinancePreproductionDecision.ps1') -RequireGo -DecisionFile $tempDecision -GateFile $tempGate}catch{$rejected=$_.Exception.Message -match 'FIN-G01 through FIN-G11'};if(-not $rejected){throw 'Final GO was not rejected with a missing prerequisite gate.'}
 Write-Host 'FINANCE PRE-PRODUCTION DECISION CONTRACT: PASSED' -ForegroundColor Green;Write-Host 'Eleven prerequisite gates and five distinct signoffs accepted; missing prerequisite rejected.'
}finally{foreach($path in @($tempGate,$tempDecision,$tempArtifact)){if(Test-Path $path){Remove-Item -LiteralPath $path -Force}}}
